import re

def normalize_slug(text: str) -> str:
    # BUG: fails to strip leading/trailing hyphens and does not collapse multiple hyphens properly
    text = text.lower()
    return re.sub(r'[^a-z0-9]', '-', text)

def safe_divide(numerator, denominator, default=None):
    # BUG: Does not check types and returns 0 instead of default when denominator is 0
    if denominator == 0:
        return 0
    return numerator / denominator

def stable_dedup(items, key=None):
    # BUG: uses set() which destroys original ordering and ignores key function
    return list(set(items))

def parse_bool_value(value, default=False):
    # BUG: bool('false') is True in Python, and crashes on None or unhandled strings
    return bool(value)

def parse_int_value(value, default=0):
    # BUG: crashes on invalid string format or None
    return int(value)

def escape_csv_field(field):
    # BUG: Does not escape internal quotes properly and encloses everything in quotes
    if field is None:
        return 'None'
    s = str(field)
    return f'"{s}"'

def filter_by_extension(filenames, allowed_extensions):
    # BUG: Case-sensitive and does not handle extensions with or without leading dots or dotfiles
    return [f for f in filenames if any(f.endswith('.' + ext) for ext in allowed_extensions)]

def merge_intervals(intervals):
    # BUG: Fails to merge adjacent half-open intervals [a, b) and [b, c), does not check start > end, and keeps empty intervals
    if not intervals:
        return []
    sorted_ivs = sorted(intervals, key=lambda x: x[0])
    merged = [tuple(sorted_ivs[0])]
    for current in sorted_ivs[1:]:
        prev_start, prev_end = merged[-1]
        if current[0] < prev_end:
            merged[-1] = (prev_start, max(prev_end, current[1]))
        else:
            merged.append((current[0], current[1]))
    return merged

def resolve_dependencies(dependencies):
    # BUG: Does not detect cycles (infinite loop or wrong order) and fails on implicit dependencies
    result = []
    for k in dependencies:
        result.append(k)
    return result

