def aggregate_user_sessions(events, session_timeout=300):
    # BUG: Assumes events are already sorted and calculates single session per user incorrectly
    users = {}
    for ev in events:
        uid = ev['user_id']
        if uid not in users:
            users[uid] = []
        users[uid].append(ev)
    return users

def compare_semver(v1: str, v2: str) -> int:
    # BUG: Lexicographical string comparison fails on multi-digit numbers like '1.10.0' vs '1.2.0'
    if v1 < v2:
        return -1
    if v1 > v2:
        return 1
    return 0

def sort_semvers(versions: list[str]) -> list[str]:
    return sorted(versions)
